firestoreRules:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /premium_keys/{keyId} {
      allow read: if true;
      allow create: if request.resource.data.status == 'active' && request.resource.data.key == keyId;
      allow update: if request.resource.data.status == resource.data.status && request.resource.data.key == resource.data.key && request.resource.data.browserId == resource.data.browserId;
      allow delete: if false;
    }
  }
}
